import assert from 'node:assert/strict';import{createRequire}from'node:module';import{readFileSync,writeFileSync}from'node:fs';import{execFileSync}from'node:child_process';import{join}from'node:path';
const root=process.argv[2],require=createRequire(join(root,'package.json')),ts=require('typescript');
const{prepareMaterialPublicSubjects}=await import(join(root,'scripts/material-public-subjects.mjs'));
const{installNgZonePublicSubject}=await import(join(root,'scripts/ng-zone-public-subjects.mjs'));
const loaded=prepareMaterialPublicSubjects(root),results=[];
function replay(path){const source=ts.createSourceFile(path,readFileSync(join(root,path),'utf8'),ts.ScriptTarget.Latest,true),cls=source.statements.find(n=>ts.isClassDeclaration(n)&&n.name.text==='_MatSnackBarContainerBase');assert.ok(cls);
 const value=ts.factory.updateClassDeclaration(cls,[ts.factory.createModifier(ts.SyntaxKind.ExportKeyword)],ts.factory.createIdentifier('Replay'),undefined,[ts.factory.createHeritageClause(ts.SyntaxKind.ExtendsKeyword,[ts.factory.createExpressionWithTypeArguments(ts.factory.createIdentifier('PortalProtocol'),undefined)])],cls.members);
 const changed=ts.transform(value,[context=>node=>{const visit=node=>ts.isDecorator(node)?undefined:ts.visitEachChild(node,visit,context);return ts.visitNode(node,visit);}]);
 try{return ts.transpileModule(ts.createPrinter().printNode(ts.EmitHint.Unspecified,changed.transformed[0],source),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;}finally{changed.dispose();}}
try{for(const model of loaded.models){installNgZonePublicSubject(model,root);writeFileSync(join(model.root,'payload.json'),JSON.stringify({original:replay('reference/material-16.2.14/snack-exit-sources/snack-bar-container.ts'),candidate:replay('projects/ngx-material-legacy/legacy-snack-bar/internal/snack-bar-container-base.ts')}));
 for(const mode of model.line==='original'?['zoneful']:['zoneful','zoneless'])for(const production of [false,true]){const script=`${production?'globalThis.ngDevMode=false;':''}
import assert from'node:assert/strict';import{readFileSync}from'node:fs';${mode==='zoneful'?"await import('zone.js/node');":''}
await import('@angular/compiler');const core=await import('@angular/core'),common=await import('@angular/common'),rx=await import('rxjs'),ops=await import('rxjs/operators');
const payload=JSON.parse(readFileSync(new URL('./payload.json',import.meta.url)));let app,zone;
${model.line==='original'?`zone=new core.NgZone({enableLongStackTrace:false});`:`const browser=await import('@angular/platform-browser');app=await browser.createApplication({providers:[core.${mode==='zoneful'?'provideZoneChangeDetection':'provideZonelessChangeDetection'}(),{provide:common.IMAGE_CONFIG,useValue:{disableImageSizeWarning:true,disableImageLazyLoadWarning:true}},{provide:core.DOCUMENT,useValue:{head:{children:[]}}},{provide:core.RendererFactory2,useValue:{createRenderer:()=>({})}}]});zone=app.injector.get(core.NgZone);`}
const injector=core.Injector.create({providers:[{provide:common.DOCUMENT,useValue:{querySelectorAll:()=>[]}}]});
async function observe(js){const exports={};new Function('exports','PortalProtocol','inject','DOCUMENT','Subject','take','uniqueId',js)(exports,class{},core.inject,common.DOCUMENT,rx.Subject,ops.take,0);
 const Type=exports.Replay;assert.equal(Type.length,5);const instance=core.runInInjectionContext(injector,()=>new Type(zone,new core.ElementRef({}),{markForCheck(){},detectChanges(){}},{FIREFOX:false},{politeness:'polite'}));let next=0,complete=0;
 instance._onExit.subscribe({next:()=>next++,complete:()=>complete++});zone.run(()=>{instance.onAnimationEnd({fromState:'visible',toState:'hidden'});assert.equal(next,0);});await new Promise(resolve=>setTimeout(resolve,0));return{next,complete};}
try{const original=await observe(payload.original),candidate=await observe(payload.candidate);assert.deepEqual(original,candidate);assert.equal(candidate.next,${mode==='zoneful'?1:0});console.log(JSON.stringify({original,candidate}));}finally{injector.destroy();app?.destroy();core.destroyPlatform();}
`;const path=join(model.root,'probe.mjs');writeFileSync(path,script);results.push({line:model.line,mode,production,...JSON.parse(execFileSync(process.execPath,[path],{cwd:model.root,encoding:'utf8',timeout:30000,maxBuffer:1024*1024}))});}}
 writeFileSync('/tmp/closeout-snack-exit-baseline-20261010.json',JSON.stringify({results,scope:'Whole base constructor/members, Angular decorators removed; portal parent, DOM, CDR, config/platform protocols. Genuine NgZone and current public-provider application. No actual native/packed legacy instances.'},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(results));
}finally{loaded.dispose();}
